+        LLUUID objId = pObj->getRootEdit() ? pObj->getRootEdit()->getID() : LLUUID::null;
+        LLUUID avId = alpha_mode_avatar_id(pObj);
+        return LLPipeline::resolveAlphaMode(objId, avId) == 1;
+    }
