+void LLScopedVelocityPolygonOffset::beginPass()
+{
+    gGL.flush();
+    glGetFloatv(GL_POLYGON_OFFSET_FACTOR, &sVelocityOffsetPassFactor);
+    glGetFloatv(GL_POLYGON_OFFSET_UNITS, &sVelocityOffsetPassUnits);
+    sVelocityOffsetPassActive = true;
