+    case 2: id = cast.getSubjectB(); break;
+    case 3: id = cast.getSubjectC(); break;
+    case 4: id = cast.getSubjectD(); break;
+    default: break;
+    }
+    if (id.isNull()) return true; // empty slot -> no-op
+    cast.setLookAtCamera(id, !cast.isLookAtCamera(id));
+    return true;
