+const char* LLViewerTexture::getVRAMPressureStatus()
+{
+    switch (sVRAMPressureState)
+    {
+        case VRAM_PRESSURE_ELEVATED:
+            return "Pressure";
+        case VRAM_PRESSURE_CRITICAL:
+            return "Critical";
+        case VRAM_PRESSURE_NORMAL:
+        default:
+            return "Normal";
+    }
+}
