+F32 LLVOAvatar::calcRiggedAlphaDepth() const
+{
+    LLViewerCamera* camera = LLViewerCamera::getInstance();
+    const LLVector3& at_axis = camera->getAtAxis();
+    if (mLastAnimExtents[0] == LLVector3() || mLastAnimExtents[1] == LLVector3())
