+glm::mat4 look(const LLVector3 pos, const LLVector3 dir, const LLVector3 up)
+{
+    LLVector3 dirN;
+    LLVector3 upN;
+    LLVector3 lftN;
+
+    lftN = dir % up;
+    lftN.normVec();
+
+    upN = lftN % dir;
+    upN.normVec();
+
+    dirN = dir;
+    dirN.normVec();
+
+    F32 ret[16];
+    ret[ 0] = lftN[0];
+    ret[ 1] = upN[0];
+    ret[ 2] = -dirN[0];
+    ret[ 3] = 0.f;
+
+    ret[ 4] = lftN[1];
+    ret[ 5] = upN[1];
+    ret[ 6] = -dirN[1];
+    ret[ 7] = 0.f;
+
+    ret[ 8] = lftN[2];
+    ret[ 9] = upN[2];
+    ret[10] = -dirN[2];
+    ret[11] = 0.f;
+
+    ret[12] = -(lftN*pos);
+    ret[13] = -(upN*pos);
+    ret[14] = dirN*pos;
+    ret[15] = 1.f;
+
+    return glm::make_mat4(ret);
+}
