+    float b0     = rim.w;
+    float b1     = b0 + max(rig_rim_globals.z, 1.0e-4);
+    float b      = smoothstep(b0, b1, -dot(v, l));
+
+    vec3  tint   = mix(vec3(1.0), diffuseColor, clamp(rig_rim_globals.w, 0.0, 1.0));
