+    settings[SETTING_GLOW]  = LLColor3(2.0f, 0.001f, -0.05f).getValue();
+
+    // Clouds off / near-zero coverage.
+    settings[SETTING_CLOUD_SHADOW]   = LLSD::Real(0.0f);
+    settings[SETTING_CLOUD_VARIANCE] = LLSD::Real(0.0f);
