+bool LLMotion::setPresentationWeight(const LLUUID& owner, F32 weight)
+{
+    if (!isPresentationControlledBy(owner) || !llfinite(weight))
+    {
+        return false;
+    }
+    mPresentationWeight = llclamp(weight, 0.f, 1.f);
+    return true;
