+
+    const LLButton* arrows[] = { mPrevArrowBtn, mNextArrowBtn, mJumpPrevArrowBtn, mJumpNextArrowBtn };
+    for (const auto* arrow : arrows)
+    {
+        if (arrow && arrow->getVisible() && arrow->getRect().pointInRect(x, y))
